<?php

/** Recognize only the exact related-object searches generated by detail pages. */
function tadlResultRelatedSearchReference($query) {
	if (!is_string($query) || !preg_match('~^\s*(?:(ca_entities|ca_places|ca_occurrences|ca_collections)\.)?(entity_id|place_id|occurrence_id|collection_id)\s*:\s*([1-9][0-9]*)\s*$~iD', $query, $matches)) {
		return null;
	}
	$tables = ['entity_id' => 'ca_entities', 'place_id' => 'ca_places', 'occurrence_id' => 'ca_occurrences', 'collection_id' => 'ca_collections'];
	$table = $tables[strtolower($matches[2])];
	$id = filter_var($matches[3], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
	if (!$id || ($matches[1] && (strtolower($matches[1]) !== $table))) { return null; }
	return ['table' => $table, 'id' => $id];
}

function tadlResultAuthorityReference(array $criterion, array $facetDefinitions) {
	if (($criterion['facet_name'] ?? '') === '_search') {
		return tadlResultRelatedSearchReference($criterion['id'] ?? null);
	}
	$info = $facetDefinitions[$criterion['facet_name'] ?? ''] ?? [];
	if (($info['type'] ?? '') !== 'authority' || !in_array($info['table'] ?? '', ['ca_entities', 'ca_places', 'ca_occurrences', 'ca_collections'], true)) { return null; }
	$value = $criterion['id'] ?? null;
	$id = (is_int($value) || is_string($value)) ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) : false;
	return $id ? ['table' => $info['table'], 'id' => $id] : null;
}

/** Read a label only after the same record, bundle and access checks as public views. */
function tadlResultAuthorityLabel($request, array $reference) {
	$subject = Datamodel::getInstance($reference['table'], true);
	if (!$subject || !$subject->load($reference['id']) || ((int)$subject->getPrimaryKey() !== $reference['id']) || ($subject->hasField('deleted') && $subject->get('deleted'))) { return null; }
	if (!$subject->isReadable($request, 'preferred_labels')) { return null; }
	if (caACLIsEnabled($subject, ['forPawtucket' => true])) {
		// Pawtucket-only ACL settings are not covered by isReadable()'s normal
		// ACL check. Filter this one ID without executing or changing a browse.
		$browse = caGetBrowseInstance($reference['table']);
		if (!$browse || !in_array($reference['id'], $browse->filterHitsByACL([$reference['id']], $subject->tableNum(), $request->getUserID()), false)) { return null; }
	} else {
		$access = caGetUserAccessValues($request);
		if ($subject->hasField('access') && is_array($access) && $access && !in_array($subject->get('access'), $access, false)) { return null; }
	}
	$label = $subject->getLabelForDisplay();
	return is_string($label) && strlen(trim($label)) ? $label : null;
}

/** Keep criterion IDs/navigation intact while removing technical queries and unsafe labels. */
function tadlResultDisplayCriteria($request, array $criteria, array $facetDefinitions) {
	foreach ($criteria as &$criterion) {
		if ($reference = tadlResultAuthorityReference($criterion, $facetDefinitions)) {
			$label = tadlResultAuthorityLabel($request, $reference);
			$criterion['value'] = $label ?? _t('Unavailable item');
			$criterion['tadl_authority'] = $label !== null ? array_merge($reference, ['label' => $label]) : null;
			if (($criterion['facet_name'] ?? '') === '_search') { $criterion['facet'] = _t('Related to'); }
		}
	}
	unset($criterion);
	return $criteria;
}

/** A related search can retain its context when users add ordinary refinements. */
function tadlResultContext($table, array $criteria) {
	if ($table !== 'ca_objects') { return null; }
	$searchCriteria = array_filter($criteria, function ($criterion) { return ($criterion['facet_name'] ?? '') === '_search'; });
	if (count($searchCriteria) === 1) {
		$criterion = reset($searchCriteria);
		$authority = $criterion['tadl_authority'] ?? null;
	} elseif (!$searchCriteria && count($criteria) === 1) {
		$criterion = reset($criteria);
		$authority = $criterion['tadl_authority'] ?? null;
	} else {
		return null;
	}
	return $authority ? array_merge($authority, ['title' => _t('Items related to %1', $authority['label'])]) : null;
}

function tadlResultItemCount($count) {
	return $count === 1 ? _t('1 item') : _t('%1 items', (int)$count);
}

function tadlResultFacetHeading(array $info) {
	if (($info['type'] ?? '') === 'authority') {
		if (($info['table'] ?? '') === 'ca_entities') { return _t('People and organizations'); }
		if (($info['table'] ?? '') === 'ca_places') { return _t('Places'); }
	}
	return $info['label_singular'] ?? '';
}
